<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('patients.manage');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$t=(int)$user['tenant_id'];$error='';if($user['role_slug']==='psychologist')$professionals=[['id'=>$user['id'],'name'=>$user['name']]];else{$st=db()->prepare("SELECT u.id,u.name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.tenant_id=:t AND u.active=1 AND (r.slug IN ('psychologist','supervised') OR (r.slug='clinic_admin' AND u.professional_crp IS NOT NULL AND u.professional_crp<>'')) ORDER BY u.name");$st->execute(['t'=>$t]);$professionals=$st->fetchAll();}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!\App\Core\Tenant::canAddPatient($t)){$error='O limite de pacientes ativos do plano atual foi atingido.';} $name=trim($_POST['name']??'');$prof=(int)($_POST['professional_id']??0);if(!$error && (strlen($name)<2||!in_array($prof,array_map(fn($p)=>(int)$p['id'],$professionals),true)))$error='Informe nome e profissional responsável.';elseif(!$error){$code='P'.date('ym').str_pad((string)random_int(1,9999),4,'0',STR_PAD_LEFT);$st=db()->prepare("INSERT INTO patients(tenant_id,primary_professional_id,code,name,preferred_name,cpf,birth_date,email,phone,emergency_contact,approach,status,created_at,updated_at) VALUES(:t,:u,:c,:n,:pn,:cpf,:bd,:e,:ph,:ec,:a,'active',NOW(),NOW())");$st->execute(['t'=>$t,'u'=>$prof,'c'=>$code,'n'=>$name,'pn'=>trim($_POST['preferred_name']??'')?:null,'cpf'=>trim($_POST['cpf']??'')?:null,'bd'=>($_POST['birth_date']??'')?:null,'e'=>trim($_POST['email']??'')?:null,'ph'=>trim($_POST['phone']??'')?:null,'ec'=>trim($_POST['emergency_contact']??'')?:null,'a'=>trim($_POST['approach']??'')?:null]);$id=(int)db()->lastInsertId();audit('patient.create','patient',$id,[]);flash('success','Paciente cadastrado.');redirect('patients/view.php?id='.$id);}}
layout('Novo paciente',function()use($professionals,$error){?><div class="page-head"><div><span class="eyebrow">Pacientes</span><h1>Novo paciente</h1><p>Cadastre apenas os dados necessários para a finalidade assistencial.</p></div></div><form method="post" class="card form-grid"><?=csrf_field()?><?php if($error):?><div class="error-box"><?=e($error)?></div><?php endif?><div class="form-row"><div class="field"><label>Nome completo</label><input name="name" required></div><div class="field"><label>Nome preferido</label><input name="preferred_name"></div></div><div class="form-row"><div class="field"><label>CPF</label><input name="cpf"></div><div class="field"><label>Nascimento</label><input type="date" name="birth_date"></div></div><div class="form-row"><div class="field"><label>E-mail</label><input type="email" name="email"></div><div class="field"><label>Telefone / WhatsApp</label><input name="phone"></div></div><div class="form-row"><div class="field"><label>Profissional responsável</label><select name="professional_id" required><?php foreach($professionals as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach?></select></div><div class="field"><label>Abordagem</label><input name="approach" placeholder="TCC, ACT, Humanista..."></div></div><div class="field"><label>Contato de emergência</label><input name="emergency_contact"></div><div><button class="button">Cadastrar paciente</button></div></form><?php },['active'=>'patients']);
